MAGIC = b"vd\x08\xed\xbe"


def _checksum(data):
    value = 0
    for offset in range(0, len(data), 4):
        value ^= int.from_bytes(data[offset:offset + 4], "little")
    return value


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    if len(data) > 65536 or len(data) < 21:
        return None
    end = len(data) - 4
    if data[:5] != MAGIC or data[5:8] != b"\x00\x00\x00":
        return None
    if int.from_bytes(data[end:], "little") != _checksum(data[:end]):
        return None
    count = data[8]
    if count > 8:
        return None

    pos = 9

    def take(n):
        nonlocal pos
        if pos + n > end:
            return None
        out = data[pos:pos + n]
        pos += n
        return out

    def text():
        raw = take(1)
        if raw is None:
            return None
        raw = take(raw[0])
        if raw is None or any(c < 0x20 or c > 0x7e for c in raw):
            return None
        return raw.decode("ascii")

    balance = take(4)
    rating = take(4)
    if balance is None or rating is None:
        return None
    records = []
    for _ in range(count):
        code = text()
        category = text()
        created_at = text()
        item_count = take(1)
        if code is None or category is None or created_at is None or item_count is None:
            return None
        records.append({
            "category": category,
            "code": code,
            "created_at": created_at,
            "item_count": item_count[0],
        })
    if pos != end:
        return None
    return {"header": {
        "balance": int.from_bytes(balance, "big"),
        "rating": int.from_bytes(rating, "big"),
    }, "records": records}
