    count = data[6]
    if count > 8:
        return None
    pos = 8

    def text():
        nonlocal pos
        if pos >= end:
            return None
        n = data[pos]; pos += 1
        if pos + n > end:
            return None
        raw = data[pos:pos + n]; pos += n
        if any(c < 0x20 or c > 0x7E for c in raw):
            return None
        return raw.decode('ascii')

    records = []
    for _ in range(count):
        rating = text()
        if rating is None or pos + 2 > end:
            return None
        amount = int.from_bytes(data[pos:pos + 2], 'little'); pos += 2
        sku = text()
        if sku is None or pos >= end:
