        account_id = data[pos]; pos += 1
        source = text()
        if source is None:
            return None
        records.append({'account_id': account_id, 'amount': amount, 'rating': rating, 'sku': sku, 'source': source})
    if pos != end:
        return None
    return {'header': {'price_cents': data[7]}, 'records': records}
