MAGIC = b'\x01\x4e\x51\x18\xe7'


def _text(data: bytes, pos: int) -> tuple[str, int] | None:
    if pos >= len(data):
        return None
    end = pos + 1 + data[pos]
    if end > len(data):
        return None
    raw = data[pos + 1:end]
    if any(byte < 0x20 or byte > 0x7e for byte in raw):
        return None
    return raw.decode('ascii'), end


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray)) or len(data) < 11:
        return None
    data = bytes(data)
    if data[:5] != MAGIC or data[6:9] != b'\0\0\0':
        return None
    count = data[5]
    if count > 8:
        return None
    balance = data[9]
    version = data[10]
    pos = 11
    records = []
    for _ in range(count):
        item = _text(data, pos)
        if item is None:
            return None
        created_at, pos = item
        item = _text(data, pos)
        if item is None:
            return None
        record_version, pos = item
        if pos + 3 > len(data):
            return None
        price_cents = data[pos]
        length = int.from_bytes(data[pos + 1:pos + 3], 'little')
        pos += 3
        records.append({'created_at': created_at, 'length': length, 'price_cents': price_cents, 'version': record_version})
    if pos != len(data):
        return None
    return {'header': {'balance': balance, 'version': version}, 'records': records}
