MAGIC = b'\x31\x87\x83\x5f\x1e'


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray)) or len(data) < 12:
        return None
    data = bytes(data)
    if data[:5] != MAGIC or data[5:8] != b'\0\0\0':
        return None
    count = data[8]
    if count > 8:
        return None
    qty = data[9]
    timestamp = int.from_bytes(data[10:12], 'little')
    pos = 12
    records = []
    for _ in range(count):
        if pos >= len(data):
            return None
        end = pos + 1 + data[pos]
        if end + 4 > len(data):
            return None
        raw = data[pos + 1:end]
        if any(byte < 0x20 or byte > 0x7e for byte in raw):
            return None
        amount = raw.decode('ascii')
        code = int.from_bytes(data[end:end + 4], 'little')
        pos = end + 4
        records.append({'amount': amount, 'code': code})
    if pos != len(data):
        return None
    return {'header': {'qty': qty, 'timestamp': timestamp}, 'records': records}
