def mk(c,q,ts,recs):
 x=bytearray(M+b'\0\0\0'+bytes([c,q])+ts.to_bytes(2,'little'))
 for s,v in recs: x += bytes([len(s)])+s+v.to_bytes(4,'little')
 return bytes(x)
for c in range(10): check('count'+str(c),mk(c,1,2,[(b'a',i) for i in range(c)]))
